1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
25	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /**
34	     * Formats the stored E.164 {@code telephone} for humans: the {@code '+'} and country code, a
35	     * space, then the national digits grouped in threes (e.g. {@code +61412345678} -&gt;
36	     * {@code +61 412 345 678}). The country code is taken as {@code 61} (Australia) or {@code 1}
37	     * (NANP) when recognised, otherwise a single leading digit. Returns {@code null} when the
38	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164
39	     * number.
40	     */
41	    default String telephoneDisplay(Owner owner) {
42	        String telephone = owner.getTelephone();
43	        if (telephone == null || telephone.isEmpty()) {
44	            return null;
45	        }
46	        if (!telephone.startsWith("+") || !telephone.substring(1).matches("\\d+")) {
47	            return telephone;
48	        }
49	        String digits = telephone.substring(1);
50	        int countryCodeLength;
51	        if (digits.startsWith("61")) {
52	            countryCodeLength = 2;
53	        }
54	        else if (digits.startsWith("1")) {
55	            countryCodeLength = 1;
56	        }
57	        else {
58	            countryCodeLength = 1;
59	        }
60	        String countryCode = digits.substring(0, countryCodeLength);
61	        String national = digits.substring(countryCodeLength);
62	        StringBuilder grouped = new StringBuilder();
63	        for (int i = 0; i < national.length(); i++) {
64	            if (i > 0 && i % 3 == 0) {
65	                grouped.append(' ');
66	            }
67	            grouped.append(national.charAt(i));
68	        }
69	        return "+" + countryCode + (national.isEmpty() ? "" : " " + grouped);
70	    }
71	
72	    /**
73	     * Derives the owner's age band from {@code birthDate} measured against {@code registrationDate}:
74	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older.
75	     * Returns {@code null} when no birthDate is recorded. When the registrationDate is absent (e.g.
76	     * legacy records) the current date is used as the reference point.
77	     */
78	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
79	        java.time.LocalDate birthDate = owner.getBirthDate();
80	        if (birthDate == null) {
81	            return null;
82	        }
83	        java.time.LocalDate reference = owner.getRegistrationDate() != null
84	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
85	        int age = java.time.Period.between(birthDate, reference).getYears();
86	        if (age < 18) {
87	            return OwnerDto.AgeBandEnum.MINOR;
88	        }
89	        if (age < 65) {
90	            return OwnerDto.AgeBandEnum.ADULT;
91	        }
92	        return OwnerDto.AgeBandEnum.SENIOR;
93	    }
94	
95	    /**
96	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is
97	     * present, otherwise {@code PHONE}.
98	     */
99	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
100	        String email = owner.getEmail();
101	        if (email != null && !email.isEmpty()) {
102	            return OwnerDto.ContactPreferenceEnum.EMAIL;
103	        }
104	        return OwnerDto.ContactPreferenceEnum.PHONE;
105	    }
106	
107	    /**
108	     * Derives the owner's locality (region) from the region-and-hash identity: it is the
109	     * {@code <REGION>} segment of the customerCode ({@code <REGION>-<HASH8>}), i.e. the region
110	     * derived from the postcode at create time. When the customerCode is absent or malformed
111	     * (e.g. legacy records), it falls back to the postcode range and then the fixed city-to-region
112	     * table, returning {@code UNKNOWN} when neither source resolves.
113	     */
114	    default String locality(Owner owner) {
115	        String code = owner.getCustomerCode();
116	        if (code != null) {
117	            int dash = code.indexOf('-');
118	            if (dash > 0) {
119	                return code.substring(0, dash);
120	            }
121	        }
122	        String region = regionFromPostcode(owner);
123	        if (region != null) {
124	            return region;
125	        }
126	        return cityRegion(owner);
127	    }
128	
129	    /**
130	     * Maps the owner's city to its region via the fixed city-to-region table
131	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Returns {@code UNKNOWN}
132	     * when the city is absent or not in the table.
133	     */
134	    default String cityRegion(Owner owner) {
135	        String city = owner.getCity();
136	        if (city == null) {
137	            return "UNKNOWN";
138	        }
139	        switch (city) {
140	            case "Sydney":
141	                return "NSW";
142	            case "Melbourne":
143	                return "VIC";
144	            case "Brisbane":
145	                return "QLD";
146	            default:
147	                return "UNKNOWN";
148	        }
149	    }
150	
151	    /**
152	     * Resolves the region from the owner's 4-digit postcode range, or {@code null}
153	     * when the postcode is absent, malformed, or in no known range.
154	     */
155	    default String regionFromPostcode(Owner owner) {
156	        String postcode = owner.getPostcode();
157	        if (postcode == null) {
158	            return null;
159	        }
160	        int code;
161	        try {
162	            code = Integer.parseInt(postcode.trim());
163	        }
164	        catch (NumberFormatException ex) {
165	            return null;
166	        }
167	        if (code >= 2000 && code <= 2099) {
168	            return "NSW";
169	        }
170	        if (code >= 3000 && code <= 3099) {
171	            return "VIC";
172	        }
173	        if (code >= 4000 && code <= 4099) {
174	            return "QLD";
175	        }
176	        return null;
177	    }
178	
179	    /**
180	     * Returns the owner's membership points. The score starts at 0 and gains 2 when an email is
181	     * present, 1 when {@code namesakeCount} is 0, 2 when the household has 3 or more members, and 3
182	     * when tenure exceeds 365 days.
183	     */
184	    default Integer membershipPoints(Owner owner) {
185	        int points = 0;
186	        String email = owner.getEmail();
187	        if (email != null && !email.isEmpty()) {
188	            points += 2;
189	        }
190	        Integer namesakeCount = owner.getNamesakeCount();
191	        if (namesakeCount != null && namesakeCount == 0) {
192	            points += 1;
193	        }
194	        Integer householdSize = owner.getHouseholdSize();
195	        if (householdSize != null && householdSize >= 3) {
196	            points += 2;
197	        }
198	        if (tenureDays(owner) > 365) {
199	            points += 3;
200	        }
201	        return points;
202	    }
203	
204	    /**
205	     * Returns the owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
206	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or
207	     * more points.
208	     */
209	    default Integer membershipLevel(Owner owner) {
210	        int points = membershipPoints(owner);
211	        if (points <= 1) {
212	            return 1;
213	        }
214	        if (points <= 3) {
215	            return 2;
216	        }
217	        if (points <= 5) {
218	            return 3;
219	        }
220	        return 4;
221	    }
222	
223	    /**
224	     * The owner's tenure in whole days: the number of days from {@code registrationDate} to the
225	     * current date. A newly created owner (registered today) has zero tenure, and a missing
226	     * registrationDate (e.g. legacy records) is likewise treated as zero.
227	     */
228	    default long tenureDays(Owner owner) {
229	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
230	        if (registrationDate == null) {
231	            return 0;
232	        }
233	        long days = java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
234	        return Math.max(days, 0);
235	    }
236	
237	    /**
238	     * Builds the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;'
239	     * where YY is the last two digits of the registrationDate year. Returns {@code null}
240	     * when either source field is absent.
241	     */
242	    default String membershipNumber(Owner owner) {
243	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
244	            return null;
245	        }
246	        return owner.getCustomerCode() + "-M"
247	            + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
248	    }
249	
250	    /**
251	     * Computes a single Luhn check digit (0-9) over the digits contained in the
252	     * owner's customerCode. Non-digit characters are ignored. Returns {@code null}
253	     * when the customerCode is absent.
254	     */
255	    default Integer checkDigit(Owner owner) {
256	        String customerCode = owner.getCustomerCode();
257	        if (customerCode == null) {
258	            return null;
259	        }
260	        int sum = 0;
261	        boolean dbl = true;
262	        for (int i = customerCode.length() - 1; i >= 0; i--) {
263	            char c = customerCode.charAt(i);
264	            if (c < '0' || c > '9') {
265	                continue;
266	            }
267	            int d = c - '0';
268	            if (dbl) {
269	                d *= 2;
270	                if (d > 9) {
271	                    d -= 9;
272	                }
273	            }
274	            sum += d;
275	            dbl = !dbl;
276	        }
277	        return (10 - (sum % 10)) % 10;
278	    }
279	
280	    Owner toOwner(OwnerDto ownerDto);
281	
282	    @Mapping(target = "id", ignore = true)
283	    @Mapping(target = "pets", ignore = true)
284	    Owner toOwner(OwnerFieldsDto ownerDto);
